definition:
/* Funcion de acceso, para que las vistas puedan leer la fecha de corte sin
   repetir el literal. */
CREATE   FUNCTION [reclamo].[fn_fecha_corte]()
RETURNS date
AS
BEGIN
    RETURN
    (
        SELECT TRY_CONVERT(date, c.valor)
        FROM [reclamo].[configuracion] c
        WHERE c.clave = 'FECHA_CORTE_SISTEMA'
    );
END;

/* ================================================================
   v2 de reclamo.sp_actualizar_disponible_rotopala y
   reclamo.sp_insertar_disponible_rotopala, con dos cambios pedidos:

   1) DENSIDAD AUTOMATICA. Si no se informa @Densidad explicita, y
      cambia TMS o m3_totales, la densidad se recalcula sola como
      TMS/m3_totales. Si se informa @Densidad, esa manda (override
      manual). Si no cambia ni TMS ni m3_totales, la densidad
      existente se conserva tal cual.

   2) PROPAGACION A MODULO YA CONGELADO. Si el (campaña_id, modulo_id)
      editado ya tiene una fila CONGELADO en reclamo.modulo_congelado,
      el cambio de tms_conformado/m3_totales/densidad_oficial se
      aplica TAMBIEN ahi (ya no queda desincronizado de disponible_
      rotopalas), y cada campo que cambio queda registrado en
      reclamo.log_sincronizacion (tabla_destino='modulo_congelado',
      tabla_origen='disponible_rotopalas (dashboard)', con valor
      anterior y nuevo). Nada de esto pasa si el modulo no esta
      congelado -- ahi disponible_rotopalas sigue siendo la unica
      fuente y modulo_congelado ni se toca.

   Ambas procedimientos devuelven, en su SELECT final, la columna
   propagado_a_modulo_congelado (bit) para que el dashboard pueda
   avisar explicitamente cuando esto ocurrio.
================================================================ */

CREATE   PROCEDURE [reclamo].[sp_actualizar_disponible_rotopala]
(
    @IdDisponibleRotopalas int,
    @Tms             decimal(30,12) = NULL,
    @M3Totales       decimal(30,12) = NULL,
    @Densidad        decimal(30,12) = NULL,
    @M3Apilado       decimal(30,12) = NULL,
    @TmhApilado      decimal(30,12) = NULL,
    @RemanenteM3     decimal(30,12) = NULL,
    @RemanenteTms    decimal(30,12) = NULL,
    @SoloInformados  bit = 1,
    @Observacion     nvarchar(500) = NULL
)
AS
BEGIN
    SET NOCOUNT ON;
    SET XACT_ABORT ON;

    IF NOT EXISTS
    (
        SELECT 1 FROM [inventar_SpcHidr].[disponible_rotopalas]
        WHERE id_disponible_rotopalas = @IdDisponibleRotopalas
    )
        THROW 61001, 'No existe ese id_disponible_rotopalas.', 1;

    IF @Densidad IS NOT NULL AND @Densidad <= 0
        THROW 61002, 'La densidad debe ser mayor a 0.', 1;

    IF @Tms IS NOT NULL AND @Tms < 0
        THROW 61003, 'El TMS no puede ser negativo.', 1;

    IF @M3Totales IS NOT NULL AND @M3Totales < 0
        THROW 61004, 'El m3_totales no puede ser negativo.', 1;

    DECLARE @PadId bigint, @ModuloId bigint, @CampañaId bigint;
    DECLARE @TmsPrevio decimal(30,12), @M3Previo decimal(30,12), @DensidadPrevia decimal(30,12);

    SELECT @PadId = pad_id, @ModuloId = modulo_id, @CampañaId = [campaña_id],
           @TmsPrevio = tms, @M3Previo = m3_totales, @DensidadPrevia = densidad
    FROM [inventar_SpcHidr].[disponible_rotopalas]
    WHERE id_disponible_rotopalas = @IdDisponibleRotopalas;

    DECLARE @TmsNuevo decimal(30,12) =
        CASE WHEN @SoloInformados = 1 THEN COALESCE(@Tms, @TmsPrevio) ELSE @Tms END;
    DECLARE @M3Nuevo decimal(30,12) =
        CASE WHEN @SoloInformados = 1 THEN COALESCE(@M3Totales, @M3Previo) ELSE @M3Totales END;

    /* Densidad automatica: manual explicita manda; si no, se recalcula
       solo cuando cambio TMS o m3_totales; si no cambio nada de eso, se
       conserva la que ya tenia (o NULL si @SoloInformados=0 y no se
       informo densidad). */
    DECLARE @DensidadNueva decimal(30,12);
    IF @Densidad IS NOT NULL
        SET @DensidadNueva = @Densidad;
    ELSE IF (@Tms IS NOT NULL OR @M3Totales IS NOT NULL) AND COALESCE(@M3Nuevo, 0) > 0
        SET @DensidadNueva = @TmsNuevo / @M3Nuevo;
    ELSE IF @SoloInformados = 1
        SET @DensidadNueva = @DensidadPrevia;
    ELSE
        SET @DensidadNueva = NULL;

    BEGIN TRANSACTION;

    UPDATE [inventar_SpcHidr].[disponible_rotopalas]
    SET tms           = @TmsNuevo,
        m3_totales    = @M3Nuevo,
        densidad      = @DensidadNueva,
        m3_apilado    = CASE WHEN @SoloInformados = 1 THEN COALESCE(@M3Apilado, m3_apilado) ELSE @M3Apilado END,
        tmh_apilado   = CASE WHEN @SoloInformados = 1 THEN COALESCE(@TmhApilado, tmh_apilado) ELSE @TmhApilado END,
        remanente_m3  = CASE WHEN @SoloInformados = 1 THEN COALESCE(@RemanenteM3, remanente_m3) ELSE @RemanenteM3 END,
        remanente_tms = CASE WHEN @SoloInformados = 1 THEN COALESCE(@RemanenteTms, remanente_tms) ELSE @RemanenteTms END
    WHERE id_disponible_rotopalas = @IdDisponibleRotopalas;

    /* Propagacion: solo si el modulo ya esta CONGELADO. */
    IF EXISTS
    (
        SELECT 1 FROM [reclamo].[modulo_congelado]
        WHERE [campaña_id] = @CampañaId AND modulo_id = @ModuloId AND estado = 'CONGELADO'
    )
    BEGIN
        DECLARE @TmsCongPrevio decimal(30,12), @M3CongPrevio decimal(30,12), @DensCongPrevia decimal(30,12);

        SELECT @TmsCongPrevio = tms_conformado, @M3CongPrevio = m3_totales, @DensCongPrevia = densidad_oficial
        FROM [reclamo].[modulo_congelado]
        WHERE [campaña_id] = @CampañaId AND modulo_id = @ModuloId AND estado = 'CONGELADO';

        UPDATE [reclamo].[modulo_congelado]
        SET tms_conformado   = @TmsNuevo,
            m3_totales       = @M3Nuevo,
            densidad_oficial = @DensidadNueva
        WHERE [campaña_id] = @CampañaId AND modulo_id = @ModuloId AND estado = 'CONGELADO';

        INSERT INTO [reclamo].[log_sincronizacion]
            (tabla_destino, tabla_origen, accion, fecha_dato,
             [campaña_id], modulo_id, campo, valor_anterior, valor_nuevo, observacion)
        SELECT
            'modulo_congelado', 'disponible_rotopalas (dashboard)', 'ACTUALIZADO',
            CAST(SYSDATETIME() AS date),
            @CampañaId, @ModuloId, cambios.campo, cambios.valor_anterior, cambios.valor_nuevo,
            COALESCE(@Observacion, N'Editado desde disponible_rotopalas; modulo ya estaba congelado.')
        FROM
        (
            VALUES
                ('tms_conformado',   @TmsCongPrevio,  @TmsNuevo),
                ('m3_totales',       @M3CongPrevio,   @M3Nuevo),
                ('densidad_oficial', @DensCongPrevia, @DensidadNueva)
        ) AS cambios(campo, valor_anterior, valor_nuevo)
        WHERE NOT
        (
            (cambios.valor_anterior IS NULL AND cambios.valor_nuevo IS NULL)
            OR (cambios.valor_anterior IS NOT NULL AND cambios.valor_nuevo IS NOT NULL
                AND cambios.valor_anterior = cambios.valor_nuevo)
        );
    END;

    COMMIT TRANSACTION;

    SELECT dr.*,
           CASE WHEN EXISTS
           (
               SELECT 1 FROM [reclamo].[modulo_congelado] mc
               WHERE mc.[campaña_id] = @CampañaId AND mc.modulo_id = @ModuloId AND mc.estado = 'CONGELADO'
           ) THEN CAST(1 AS bit) ELSE CAST(0 AS bit) END AS propagado_a_modulo_congelado
    FROM [inventar_SpcHidr].[disponible_rotopalas] dr
    WHERE dr.id_disponible_rotopalas = @IdDisponibleRotopalas;
END;

/* ============================================================================
   SP 5. reclamo.sp_aprobar_ajuste_manual

   Separa quien propone de quien aprueba. El procedimiento impide que ambos
   sean el mismo login, salvo que se pase @PermitirAutoaprobacion = 1, lo que
   queda anotado en la observacion.
   ============================================================================ */
CREATE   PROCEDURE [reclamo].[sp_aprobar_ajuste_manual]
(
    @AjusteId                int,
    @Decision                varchar(20),
    @Comentario              nvarchar(500) = NULL,
    @PermitirAutoaprobacion  bit = 0
)
AS
BEGIN
    SET NOCOUNT ON;
    SET XACT_ABORT ON;

    IF @Decision NOT IN ('APROBADO','RECHAZADO','REVERTIDO')
        THROW 60401, 'La decision debe ser APROBADO, RECHAZADO o REVERTIDO.', 1;

    DECLARE @Solicitante sysname =
    (
        SELECT usuario_solicita FROM [reclamo].[ajuste_manual] WHERE ajuste_id = @AjusteId
    );

    IF @Solicitante IS NULL
        THROW 60402, 'No existe ese ajuste.', 1;

    IF @Solicitante = SUSER_SNAME() AND @PermitirAutoaprobacion = 0
        THROW 60403,
              'Quien propone un ajuste no deberia aprobarlo. Use @PermitirAutoaprobacion = 1 si corresponde.', 1;

    UPDATE [reclamo].[ajuste_manual]
    SET estado           = @Decision,
        usuario_aprueba  = SUSER_SNAME(),
        fecha_aprobacion = SYSDATETIME(),
        observacion      = LTRIM(RTRIM(COALESCE(observacion, N'')
                           + N' | ' + @Decision + N': ' + COALESCE(@Comentario, N'sin comentario')
                           + CASE WHEN @PermitirAutoaprobacion = 1
                                  THEN N' | AUTOAPROBADO POR EL SOLICITANTE' ELSE N'' END))
    WHERE ajuste_id = @AjusteId;

    PRINT 'Ajuste ' + CAST(@AjusteId AS varchar) + ' -> ' + @Decision;
    PRINT 'Recuerde reprocesar el rango con sp_calcular_reclamo_diario.';

    SELECT * FROM [reclamo].[ajuste_manual] WHERE ajuste_id = @AjusteId;
END;

/* ============================================================================
   SP 3.e reclamo.sp_auto_mantener_secuencia

   Orquestador. Es lo que llama el boton del dashboard: el usuario no corre
   EXEC en la base de datos. Primero rellena secuencias huerfanas (modulos
   CONGELADOS de antes de esta automatizacion que nunca llegaron a tener
   fila en secuencia_rotopala), despues cierra y avanza (libera cupo),
   despues congela lo nuevo y precongela lo que viene (y abre lo que ya
   tiene movimiento si quedo cupo). Deja todo en reclamo.log_automatizacion
   y devuelve esa bitacora, ordenada con las alertas primero.

   Backfill de secuencia (agregado 2026-07-30): reclamo.sp_definir_secuencia
   ya se llamaba automaticamente para cada modulo recien congelado (dentro
   de sp_auto_congelar_modulos_nuevos), pero eso no alcanza a los modulos
   que quedaron CONGELADOS antes de que existiera esta automatizacion --
   confirmado en los modulos 125 a 140 de rotopala 2 / campaña 8, todos
   congelados en bloque el 2026-07-29 sin pasar por el flujo automatico, y
   por lo tanto sin fila en secuencia_rotopala. Sin este backfill, cuando el
   modulo 124 se cerraba por avance de secuencia, sp_auto_cerrar_y_avanzar_
   secuencia no encontraba un modulo 125 al cual abrir (porque no existia
   como PENDIENTE) y quedaba en ALERTA_FIN_DE_CAMPANA con un mensaje
   enganoso ("no hay mas modulos congelados"), cuando en realidad si los
   habia, solo que nunca se habian secuenciado. sp_definir_secuencia es
   idempotente: solo agrega los modulos que faltan, nunca reordena ni borra
   los que ya estan.
   ============================================================================ */
CREATE   PROCEDURE [reclamo].[sp_auto_mantener_secuencia]
(
    @VentanaDias int = 90,
    @Siguientes  int = 5
)
AS
BEGIN
    SET NOCOUNT ON;
    SET XACT_ABORT ON;

    INSERT INTO [reclamo].[log_ejecucion] (procedimiento, estado)
    VALUES ('reclamo.sp_auto_mantener_secuencia', 'EN_CURSO');
    DECLARE @EjecucionId int = SCOPE_IDENTITY();

    BEGIN TRY
        IF EXISTS
        (
            SELECT 1
            FROM [reclamo].[modulo_congelado] mc
            WHERE mc.estado = 'CONGELADO'
              AND NOT EXISTS
              (
                  SELECT 1 FROM [reclamo].[secuencia_rotopala] s
                  WHERE s.[campaña_id] = mc.[campaña_id] AND s.modulo_id = mc.modulo_id
              )
        )
        BEGIN
            DECLARE @CampDef int, @PadDef int;
            DECLARE campañas_def CURSOR LOCAL FAST_FORWARD FOR
                SELECT DISTINCT mc.[campaña_id], mc.pad_id
                FROM [reclamo].[modulo_congelado] mc
                WHERE mc.estado = 'CONGELADO'
                  AND NOT EXISTS
                  (
                      SELECT 1 FROM [reclamo].[secuencia_rotopala] s
                      WHERE s.[campaña_id] = mc.[campaña_id] AND s.modulo_id = mc.modulo_id
                  );
            OPEN campañas_def;
            FETCH NEXT FROM campañas_def INTO @CampDef, @PadDef;
            WHILE @@FETCH_STATUS = 0
            BEGIN
                BEGIN TRY
                    EXEC [reclamo].[sp_definir_secuencia]
                         @CampañaId = @CampDef, @PadId = @PadDef;

                    INSERT INTO [reclamo].[log_automatizacion]
                        (ejecucion_id, accion, pad_id, [campaña_id], detalle)
                    VALUES
                        (@EjecucionId, 'SECUENCIADO_AUTOMATICO', @PadDef, @CampDef,
                         N'Backfill: se agregaron a secuencia_rotopala los modulos '
                            + N'CONGELADOS de esta campana/pad que no tenian fila.');
                END TRY
                BEGIN CATCH
                    INSERT INTO [reclamo].[log_automatizacion]
                        (ejecucion_id, accion, pad_id, [campaña_id], detalle)
                    VALUES
                        (@EjecucionId, 'ALERTA_SIN_BASE', @PadDef, @CampDef,
                         N'Error en backfill de secuencia: ' + ERROR_MESSAGE());
                END CATCH;
                FETCH NEXT FROM campañas_def INTO @CampDef, @PadDef;
            END;
            CLOSE campañas_def;
            DEALLOCATE campañas_def;
        END;

        EXEC [reclamo].[sp_auto_cerrar_y_avanzar_secuencia] @EjecucionId = @EjecucionId;

        EXEC [reclamo].[sp_auto_congelar_modulos_nuevos]
             @VentanaDias = @VentanaDias, @Siguientes = @Siguientes, @EjecucionId = @EjecucionId;

        /* -------------------------------------------------------------
           Relleno de cupo huerfano (agregado 2026-07-30, corregido el
           mismo dia): si una rotopala/campaña queda con CERO modulos
           ABIERTO pero SI tiene al menos un CERRADO (caso del modulo 124:
           se cerro en una corrida anterior a que existiera el backfill de
           secuencia de mas arriba, asi que su sucesor nunca se abrio
           porque el paso "abrir el siguiente" solo se dispara como efecto
           inmediato de cerrar dentro de la MISMA corrida), abre el
           siguiente PENDIENTE por orden_secuencia.

           Version anterior (incorrecta, descartada): exigia solo que
           existiera ALGUNA medicion VIGENTE en topografia_avance, sin
           mirar la fecha. Se comprobo en la rotopala 2 / campaña 8 que
           eso abre el modulo equivocado: los modulos 103 a 123 llevaban
           meses (abril a julio) ya extraidos casi al 100 % por camiones,
           congelados en bloque el 2026-07-29 sin nunca pasar por
           secuencia, y el 123 en particular tenia 4 mediciones VIGENTE
           pero todas de 2026-07-01 a 2026-07-04 -- anteriores incluso al
           124 (que midio hasta el 07-08). Al ordenar por orden_secuencia,
           que sp_definir_secuencia asigna por modulo_numero ascendente,
           123 quedaba antes que 125 y se abria primero aunque su ultima
           actividad real fuera mas vieja que la del propio modulo que se
           acababa de cerrar.

           Fix: la evidencia ahora exige que la medicion VIGENTE sea
           POSTERIOR a la ultima medicion real de los modulos ya CERRADOS
           de esa misma rotopala/campaña (mismo principio de "solo cola"
           que v_preliminar_cv25 y AVANCE_DE_SECUENCIA). Con esto, 123
           queda descartado (su ultima medicion, 07-04, es anterior al
           07-08 del 124) y el candidato correcto pasa a ser 125 (mide
           desde el 07-09, despues del 124).
        ------------------------------------------------------------- */
        DECLARE @RotRell tinyint, @CampRell int;
        DECLARE @SecRell int, @ModRell int, @PadRell int, @ModNumRell int;
        DECLARE @UltimaMedicionCerrado date;

        DECLARE grupos_relleno CURSOR LOCAL FAST_FORWARD FOR
            SELECT DISTINCT s.rotopala_id, s.[campaña_id]
            FROM [reclamo].[secuencia_rotopala] s
            WHERE NOT EXISTS
            (
                SELECT 1 FROM [reclamo].[secuencia_rotopala] s2
                WHERE s2.rotopala_id = s.rotopala_id AND s2.[campaña_id] = s.[campaña_id]
                  AND s2.estado = 'ABIERTO'
            )
            AND EXISTS
            (
                SELECT 1 FROM [reclamo].[secuencia_rotopala] s3
                WHERE s3.rotopala_id = s.rotopala_id AND s3.[campaña_id] = s.[campaña_id]
                  AND s3.estado = 'CERRADO'
            );
        OPEN grupos_relleno;
        FETCH NEXT FROM grupos_relleno INTO @RotRell, @CampRell;
        WHILE @@FETCH_STATUS = 0
        BEGIN
            SET @SecRell = NULL;

            SET @UltimaMedicionCerrado =
            (
                SELECT MAX(t.fecha_medicion)
                FROM [reclamo].[secuencia_rotopala] s4
                INNER JOIN [reclamo].[topografia_avance] t
                        ON t.modulo_id = s4.modulo_id AND t.estado = 'VIGENTE'
                WHERE s4.rotopala_id = @RotRell AND s4.[campaña_id] = @CampRell
                  AND s4.estado = 'CERRADO'
            );

            SELECT TOP (1)
                @SecRell = s.secuencia_id, @ModRell = s.modulo_id,
                @PadRell = s.pad_id, @ModNumRell = s.modulo_numero
            FROM [reclamo].[secuencia_rotopala] s
            WHERE s.rotopala_id = @RotRell AND s.[campaña_id] = @CampRell
              AND s.estado = 'PENDIENTE'
              AND EXISTS
              (
                  SELECT 1 FROM [reclamo].[topografia_avance] t
                  WHERE t.modulo_id = s.modulo_id AND t.estado = 'VIGENTE'
                    AND
                    (
                        @UltimaMedicionCerrado IS NULL
                        OR t.fecha_medicion > @UltimaMedicionCerrado
                    )
              )
            ORDER BY s.orden_secuencia ASC;

            IF @SecRell IS NOT NULL
            BEGIN
                UPDATE [reclamo].[secuencia_rotopala]
                SET estado = 'ABIERTO', fecha_apertura = CAST(SYSDATETIME() AS date)
                WHERE secuencia_id = @SecRell;

                INSERT INTO [reclamo].[log_automatizacion]
                    (ejecucion_id, accion, pad_id, [campaña_id], modulo_id, modulo_numero, detalle)
                VALUES
                    (@EjecucionId, 'ABIERTO_AUTOMATICO', @PadRell, @CampRell, @ModRell, @ModNumRell,
                     N'Rotopala sin modulo ABIERTO tras el backfill de secuencia. Se abre el '
                        + N'siguiente PENDIENTE con medicion real de topografia POSTERIOR a la '
                        + N'ultima medicion de los modulos ya cerrados (evidencia fisica de '
                        + N'actividad reciente, no se abre solo por haber cupo ni por tener '
                        + N'cualquier medicion historica).');
            END;

            FETCH NEXT FROM grupos_relleno INTO @RotRell, @CampRell;
        END;
        CLOSE grupos_relleno;
        DEALLOCATE grupos_relleno;

        DECLARE @Congelados int, @Abiertos int, @Cerrados int, @Alertas int;
        SELECT
            @Congelados = SUM(CASE WHEN accion = 'CONGELADO_AUTOMATICO' THEN 1 ELSE 0 END),
            @Abiertos   = SUM(CASE WHEN accion = 'ABIERTO_AUTOMATICO'   THEN 1 ELSE 0 END),
            @Cerrados   = SUM(CASE WHEN accion = 'CERRADO_AUTOMATICO'   THEN 1 ELSE 0 END),
            @Alertas    = SUM(CASE WHEN accion LIKE 'ALERTA%'           THEN 1 ELSE 0 END)
        FROM [reclamo].[log_automatizacion]
        WHERE ejecucion_id = @EjecucionId;

        PRINT 'Congelados automaticamente : ' + CAST(COALESCE(@Congelados,0) AS varchar);
        PRINT 'Abiertos automaticamente   : ' + CAST(COALESCE(@Abiertos,0) AS varchar);
        PRINT 'Cerrados automaticamente   : ' + CAST(COALESCE(@Cerrados,0) AS varchar);
        PRINT 'Alertas para revisar       : ' + CAST(COALESCE(@Alertas,0) AS varchar);

        UPDATE [reclamo].[log_ejecucion]
        SET fecha_fin       = SYSDATETIME(),
            filas_afectadas = COALESCE(@Congelados,0) + COALESCE(@Abiertos,0) + COALESCE(@Cerrados,0),
            estado          = 'OK'
        WHERE ejecucion_id = @EjecucionId;

        SELECT
            l.log_id, l.accion, l.pad_id, l.[campaña_id], l.modulo_id, l.modulo_numero,
            l.detalle, l.fecha_evento
        FROM [reclamo].[log_automatizacion] l
        WHERE l.ejecucion_id = @EjecucionId
        ORDER BY CASE WHEN l.accion LIKE 'ALERTA%' THEN 0 ELSE 1 END, l.log_id;
    END TRY
    BEGIN CATCH
        UPDATE [reclamo].[log_ejecucion]
        SET fecha_fin = SYSDATETIME(), estado = 'ERROR', mensaje = ERROR_MESSAGE()
        WHERE ejecucion_id = @EjecucionId;
        THROW;
    END CATCH
END;

/* ============================================================================
   SP 1. reclamo.sp_congelar_modulo

   Regla R1. Toma el tonelaje conformado desde modulos_turnos y el volumen y
   densidad desde disponible_rotopalas, y los congela.

   Un modulo ya congelado NO se puede volver a congelar sin @Forzar = 1, y esa
   accion queda registrada en la observacion.
   ============================================================================ */
CREATE   PROCEDURE [reclamo].[sp_congelar_modulo]
(
    @CampañaId          int,
    @ModuloId           int,
    @PadId              int,
    @ParcelaId          int          = NULL,
    @FechaConformacion  date         = NULL,
    @Forzar             bit          = 0,
    @Observacion        nvarchar(1000) = NULL
)
AS
BEGIN
    SET NOCOUNT ON;
    SET XACT_ABORT ON;

    IF @CampañaId IS NULL OR @ModuloId IS NULL OR @PadId IS NULL
        THROW 60001, 'Debe informar campana, modulo y PAD.', 1;

    DECLARE @Existe int =
    (
        SELECT COUNT(*)
        FROM [reclamo].[modulo_congelado]
        WHERE [campaña_id] = @CampañaId AND modulo_id = @ModuloId
    );

    IF @Existe > 0 AND @Forzar = 0
        THROW 60002,
              'El modulo ya esta congelado. Use @Forzar = 1 y explique el motivo en @Observacion.', 1;

    IF @Existe > 0 AND @Forzar = 1 AND @Observacion IS NULL
        THROW 60003,
              'Recongelar un modulo exige @Observacion con el motivo.', 1;

    /* ---- Base oficial: disponible_rotopalas -------------------------------
       CORRECCION 30-07-2026. El diseno original tomaba el TMS de la suma de
       modulos_turnos. El script 00 mostro que esa suma esta un orden por
       encima del valor de disponible_rotopalas, que es ademas el que usa la
       hoja "Disponible para rotopalas" del libro de ripios.
       disponible_rotopalas manda; modulos_turnos queda como contraste. */
    DECLARE @Tms      decimal(30,12);
    DECLARE @M3       decimal(30,12);
    DECLARE @Densidad decimal(30,12);

    SELECT TOP (1)
        @Tms      = CAST(dr.[tms]        AS decimal(30,12)),
        @M3       = CAST(dr.[m3_totales] AS decimal(30,12)),
        @Densidad = CAST(dr.[densidad]   AS decimal(30,12))
    FROM [inventar_SpcHidr].[disponible_rotopalas] dr
    WHERE dr.[campaña_id] = @CampañaId
      AND dr.[modulo_id]  = @ModuloId;

    IF @Tms IS NULL OR @Tms <= 0
        THROW 60004,
              'disponible_rotopalas no tiene tms para esa campana y modulo.', 1;

    IF @M3 IS NULL OR @M3 <= 0
        THROW 60005,
              'disponible_rotopalas no tiene m3_totales para esa campana y modulo.', 1;

    /* Si la densidad declarada no viene o es cero, se deriva del cociente. */
    IF COALESCE(@Densidad, 0) <= 0
        SET @Densidad = @Tms / @M3;

    /* Contraste con modulos_turnos, solo informativo. */
    DECLARE @TmsTurnos decimal(30,12) =
    (
        SELECT SUM(COALESCE(mt.[TMS], 0))
        FROM [inventar_SpcHidr].[modulos_turnos] mt
        WHERE mt.[campaña_id] = @CampañaId
          AND mt.[modulo_id]  = @ModuloId
    );

    IF @TmsTurnos IS NOT NULL AND @Tms > 0
       AND ABS(@TmsTurnos - @Tms) * 100.0 / @Tms > 10
        PRINT '        AVISO: modulos_turnos suma ' + CAST(@TmsTurnos AS varchar(40))
            + ' TMS y disponible_rotopalas informa ' + CAST(@Tms AS varchar(40))
            + '. Se congela con disponible_rotopalas.';

    /* Parcela y PAD se derivan de la jerarquia real pad > parcela > modulo,
       confirmada en el script 00 seccion 4. */
    IF @ParcelaId IS NULL
        SELECT @ParcelaId = md.id_parcela
        FROM [inventar_SpcHidr].[modulo] md
        WHERE md.id_modulo = @ModuloId;

    DECLARE @ModuloNumero int =
    (
        SELECT TOP (1) md.numero
        FROM [inventar_SpcHidr].[modulo] md
        WHERE md.id_modulo = @ModuloId
    );

    /* El numero de modulo debe caer dentro del rango fisico del PAD.
       Oxido: 32 parcelas x 2 modulos = 1 a 64.
       Sulfuro: 28 parcelas x 5 modulos = 1 a 140. */
    DECLARE @Min int, @Max int, @PadNombre varchar(40);
    SELECT @Min = tp.modulo_numero_min,
           @Max = tp.modulo_numero_max,
           @PadNombre = tp.nombre
    FROM [reclamo].[topologia_pad] tp
    WHERE tp.pad_id = @PadId;

    IF @Min IS NULL
        THROW 60006,
              'No hay topologia definida para ese PAD. Revise reclamo.topologia_pad.', 1;

    IF @ModuloNumero IS NOT NULL AND @ModuloNumero NOT BETWEEN @Min AND @Max
    BEGIN
        DECLARE @Msg nvarchar(300) =
            N'El modulo ' + CAST(@ModuloNumero AS nvarchar(10))
            + N' esta fuera del rango del ' + @PadNombre
            + N' (' + CAST(@Min AS nvarchar(10)) + N' a ' + CAST(@Max AS nvarchar(10)) + N').';
        THROW 60007, @Msg, 1;
    END;

    IF @Existe > 0
    BEGIN
        UPDATE [reclamo].[modulo_congelado]
        SET pad_id              = @PadId,
            parcela_id          = @ParcelaId,
            modulo_numero       = @ModuloNumero,
            fecha_conformacion  = COALESCE(@FechaConformacion, fecha_conformacion),
            fecha_congelamiento = CAST(SYSDATETIME() AS date),
            tms_conformado      = @Tms,
            m3_totales          = @M3,
            densidad_oficial    = @Densidad,
            fuente              = 'DISPONIBLE_ROTOPALAS',
            metodo              = 'RECONGELADO_FORZADO',
            usuario_registro    = SUSER_SNAME(),
            fecha_registro      = SYSDATETIME(),
            observacion         = @Observacion
        WHERE [campaña_id] = @CampañaId AND modulo_id = @ModuloId;

        PRINT 'Modulo RECONGELADO. Campana ' + CAST(@CampañaId AS varchar)
            + ' modulo ' + CAST(@ModuloId AS varchar);
    END
    ELSE
    BEGIN
        INSERT INTO [reclamo].[modulo_congelado]
        (
            [campaña_id], pad_id, parcela_id, modulo_id, modulo_numero,
            fecha_conformacion, fecha_congelamiento,
            tms_conformado, m3_totales, densidad_oficial,
            fuente, metodo, estado, observacion
        )
        VALUES
        (
            @CampañaId, @PadId, @ParcelaId, @ModuloId, @ModuloNumero,
            COALESCE(@FechaConformacion, CAST(SYSDATETIME() AS date)),
            CAST(SYSDATETIME() AS date),
            @Tms, @M3, @Densidad,
            'DISPONIBLE_ROTOPALAS',
            'TMS_Y_VOLUMEN_DE_DISPONIBLE_ROTOPALAS',
            'CONGELADO', @Observacion
        );

        PRINT 'Modulo CONGELADO. Campana ' + CAST(@CampañaId AS varchar)
            + ' modulo ' + CAST(@ModuloId AS varchar)
            + ' TMS ' + CAST(@Tms AS varchar(40))
            + ' m3 '  + CAST(@M3 AS varchar(40));
    END;

    SELECT *
    FROM [reclamo].[modulo_congelado]
    WHERE [campaña_id] = @CampañaId AND modulo_id = @ModuloId;
END;

CREATE   PROCEDURE [reclamo].[sp_insertar_disponible_rotopala]
(
    @PadId           bigint,
    @ModuloId        bigint,
    @CampañaId       bigint,
    @Campaña         int            = NULL,
    @Tms             decimal(30,12) = NULL,
    @M3Totales       decimal(30,12) = NULL,
    @Densidad        decimal(30,12) = NULL,
    @M3Apilado       decimal(30,12) = NULL,
    @TmhApilado      decimal(30,12) = NULL,
    @RemanenteM3     decimal(30,12) = NULL,
    @RemanenteTms    decimal(30,12) = NULL,
    @Observacion     nvarchar(500) = NULL
)
AS
BEGIN
    SET NOCOUNT ON;
    SET XACT_ABORT ON;

    DECLARE @ModuloNumero int =
        (SELECT numero FROM [inventar_SpcHidr].[modulo] WHERE id_modulo = @ModuloId);

    IF @ModuloNumero IS NULL
        THROW 61011, 'modulo_id no existe en inventar_SpcHidr.modulo.', 1;

    IF EXISTS
    (
        SELECT 1 FROM [inventar_SpcHidr].[disponible_rotopalas]
        WHERE pad_id = @PadId AND modulo_id = @ModuloId AND [campaña_id] = @CampañaId
    )
        THROW 61012,
              'Ya existe un registro para ese pad_id, modulo_id y campaña_id. Use sp_actualizar_disponible_rotopala.', 1;

    IF @Campaña IS NULL
        SELECT TOP (1) @Campaña = dr.[campaña]
        FROM [inventar_SpcHidr].[disponible_rotopalas] dr
        WHERE dr.[campaña_id] = @CampañaId;

    IF @Campaña IS NULL
        THROW 61013,
              'No se pudo determinar el numero de campaña visible (@Campaña). Informelo explicitamente.', 1;

    IF @Densidad IS NOT NULL AND @Densidad <= 0
        THROW 61014, 'La densidad debe ser mayor a 0.', 1;

    IF @Tms IS NOT NULL AND @Tms < 0
        THROW 61015, 'El TMS no puede ser negativo.', 1;

    IF @M3Totales IS NOT NULL AND @M3Totales < 0
        THROW 61016, 'El m3_totales no puede ser negativo.', 1;

    /* Densidad automatica, igual criterio que en la actualizacion. */
    IF @Densidad IS NULL AND @Tms IS NOT NULL AND COALESCE(@M3Totales, 0) > 0
        SET @Densidad = @Tms / @M3Totales;

    BEGIN TRANSACTION;

    INSERT INTO [inventar_SpcHidr].[disponible_rotopalas]
    (
        pad_id, modulo, modulo_id, [campaña], [campaña_id],
        tms, m3_totales, densidad, m3_apilado, tmh_apilado,
        remanente_m3, remanente_tms
    )
    VALUES
    (
        @PadId, @ModuloNumero, @ModuloId, @Campaña, @CampañaId,
        @Tms, @M3Totales, @Densidad, @M3Apilado, @TmhApilado,
        @RemanenteM3, @RemanenteTms
    );

    /* Caso borde: si por alguna razon ya existia una linea base congelada
       para este modulo/campaña (por ejemplo, se recreo una fila borrada),
       se propaga y se deja registro igual que en la actualizacion. */
    IF EXISTS
    (
        SELECT 1 FROM [reclamo].[modulo_congelado]
        WHERE [campaña_id] = @CampañaId AND modulo_id = @ModuloId AND estado = 'CONGELADO'
    )
    BEGIN
        DECLARE @TmsCongPrevio2 decimal(30,12), @M3CongPrevio2 decimal(30,12), @DensCongPrevia2 decimal(30,12);

        SELECT @TmsCongPrevio2 = tms_conformado, @M3CongPrevio2 = m3_totales, @DensCongPrevia2 = densidad_oficial
        FROM [reclamo].[modulo_congelado]
        WHERE [campaña_id] = @CampañaId AND modulo_id = @ModuloId AND estado = 'CONGELADO';

        UPDATE [reclamo].[modulo_congelado]
        SET tms_conformado   = COALESCE(@Tms, tms_conformado),
            m3_totales       = COALESCE(@M3Totales, m3_totales),
            densidad_oficial = COALESCE(@Densidad, densidad_oficial)
        WHERE [campaña_id] = @CampañaId AND modulo_id = @ModuloId AND estado = 'CONGELADO';

        INSERT INTO [reclamo].[log_sincronizacion]
            (tabla_destino, tabla_origen, accion, fecha_dato,
             [campaña_id], modulo_id, campo, valor_anterior, valor_nuevo, observacion)
        SELECT
            'modulo_congelado', 'disponible_rotopalas (dashboard)', 'ACTUALIZADO',
            CAST(SYSDATETIME() AS date),
            @CampañaId, @ModuloId, cambios.campo, cambios.valor_anterior, cambios.valor_nuevo,
            COALESCE(@Observacion, N'Insertado en disponible_rotopalas; el modulo ya estaba congelado.')
        FROM
        (
            VALUES
                ('tms_conformado',   @TmsCongPrevio2,  COALESCE(@Tms, @TmsCongPrevio2)),
                ('m3_totales',       @M3CongPrevio2,   COALESCE(@M3Totales, @M3CongPrevio2)),
                ('densidad_oficial', @DensCongPrevia2, COALESCE(@Densidad, @DensCongPrevia2))
        ) AS cambios(campo, valor_anterior, valor_nuevo)
        WHERE NOT
        (
            (cambios.valor_anterior IS NULL AND cambios.valor_nuevo IS NULL)
            OR (cambios.valor_anterior IS NOT NULL AND cambios.valor_nuevo IS NOT NULL
                AND cambios.valor_anterior = cambios.valor_nuevo)
        );
    END;

    COMMIT TRANSACTION;

    SELECT dr.*,
           CASE WHEN EXISTS
           (
               SELECT 1 FROM [reclamo].[modulo_congelado] mc
               WHERE mc.[campaña_id] = @CampañaId AND mc.modulo_id = @ModuloId AND mc.estado = 'CONGELADO'
           ) THEN CAST(1 AS bit) ELSE CAST(0 AS bit) END AS propagado_a_modulo_congelado
    FROM [inventar_SpcHidr].[disponible_rotopalas] dr
    WHERE dr.pad_id = @PadId AND dr.modulo_id = @ModuloId AND dr.[campaña_id] = @CampañaId;
END;

/* ============================================================================
   SP 4. reclamo.sp_registrar_ajuste_manual

   Regla R10. El ajuste nace en estado PROPUESTO y no afecta ninguna cifra
   hasta que se apruebe. Exige motivo y antecedente: la restriccion no es
   opcional y esta ademas en el modelo.
   ============================================================================ */
CREATE   PROCEDURE [reclamo].[sp_registrar_ajuste_manual]
(
    @FechaOperacion   date,
    @CampañaId        int,
    @PadId            int,
    @ModuloId         int,
    @TipoAjuste       varchar(30),
    @Motivo           nvarchar(500),
    @AntecedenteTipo  varchar(40),
    @AntecedenteRef   nvarchar(500),
    @DeltaM3          decimal(30,12) = NULL,
    @DeltaTms         decimal(30,12) = NULL,
    @ModuloDestinoId  int            = NULL,
    @Observacion      nvarchar(1000) = NULL
)
AS
BEGIN
    SET NOCOUNT ON;
    SET XACT_ABORT ON;

    IF @Motivo IS NULL OR LTRIM(RTRIM(@Motivo)) = ''
        THROW 60301, 'Todo ajuste manual exige un motivo.', 1;

    IF @AntecedenteRef IS NULL OR LTRIM(RTRIM(@AntecedenteRef)) = ''
        THROW 60302,
              'Todo ajuste manual exige la referencia del antecedente que lo respalda.', 1;

    IF @DeltaM3 IS NULL AND @DeltaTms IS NULL
        THROW 60303, 'Debe informar al menos delta en m3 o en TMS.', 1;

    IF @TipoAjuste = 'TRASPASO_MODULO' AND @ModuloDestinoId IS NULL
        THROW 60304, 'Un traspaso exige el modulo destino.', 1;

    /* Si viene solo uno de los dos deltas, se deriva el otro con la densidad
       oficial del modulo. Deja constancia en la observacion. */
    DECLARE @Densidad decimal(30,12) =
    (
        SELECT TOP (1) mc.densidad_oficial
        FROM [reclamo].[modulo_congelado] mc
        WHERE mc.[campaña_id] = @CampañaId AND mc.modulo_id = @ModuloId
    );

    DECLARE @Derivado nvarchar(200) = NULL;

    IF @DeltaM3 IS NULL AND @DeltaTms IS NOT NULL AND COALESCE(@Densidad,0) > 0
    BEGIN
        SET @DeltaM3 = @DeltaTms / @Densidad;
        SET @Derivado = N'delta_m3 derivado de delta_tms con densidad oficial '
                      + CAST(@Densidad AS nvarchar(40));
    END;

    IF @DeltaTms IS NULL AND @DeltaM3 IS NOT NULL AND COALESCE(@Densidad,0) > 0
    BEGIN
        SET @DeltaTms = @DeltaM3 * @Densidad;
        SET @Derivado = N'delta_tms derivado de delta_m3 con densidad oficial '
                      + CAST(@Densidad AS nvarchar(40));
    END;

    INSERT INTO [reclamo].[ajuste_manual]
    (
        fecha_operacion, [campaña_id], pad_id, modulo_id, modulo_destino_id,
        tipo_ajuste, delta_m3, delta_tms,
        motivo, antecedente_tipo, antecedente_ref,
        estado, observacion
    )
    VALUES
    (
        @FechaOperacion, @CampañaId, @PadId, @ModuloId, @ModuloDestinoId,
        @TipoAjuste, @DeltaM3, @DeltaTms,
        @Motivo, @AntecedenteTipo, @AntecedenteRef,
        'PROPUESTO',
        LTRIM(RTRIM(COALESCE(@Observacion, N'') + N' ' + COALESCE(@Derivado, N'')))
    );

    DECLARE @Id int = SCOPE_IDENTITY();

    PRINT 'Ajuste registrado en estado PROPUESTO. ajuste_id = ' + CAST(@Id AS varchar);
    PRINT 'No afecta ninguna cifra hasta que se apruebe con sp_aprobar_ajuste_manual.';

    SELECT * FROM [reclamo].[ajuste_manual] WHERE ajuste_id = @Id;
END;
